<?php require __DIR__.'/includes/functions.php'; $error=''; if($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); try { rate_limit('contact',5); q('INSERT INTO contact_messages(name,email,subject,message) VALUES(?,?,?,?)',[require_text(post('name'),'Name',2,100),email_value(post('email')),require_text(post('subject'),'Subject',3,150),require_text(post('message'),'Message',10,5000)]); flash('Message received. Thank you for reaching out.'); go('contact.php'); } catch(DomainException $ex) { $error=$ex->getMessage(); } } $title='Let’s talk'; require ROOT.'/includes/header.php'; ?>
<section class="auth-layout"><div class="auth-story"><p class="eyebrow">WE’RE HERE FOR YOU</p><h1>Let’s <span class="gradient-text">talk.</span></h1><p>A question about your next favorite? Need help with an order? Leave us a message.</p><div class="glass p-4 mt-4"><h3>Already placed an order?</h3><p>Include your NX order number so we can find your details.</p><a href="<?= url('orders.php') ?>">View your orders ↗</a></div></div><div class="glass auth-card"><h2>Send a message</h2><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post"><?= csrf() ?><?php foreach(['name'=>'Your name','email'=>'Email','subject'=>'Subject'] as $key=>$label): ?><label><?= $label ?><input name="<?= $key ?>" type="<?= $key==='email'?'email':'text' ?>" class="form-control" value="<?= e(post($key)) ?>" required maxlength="<?= $key==='email'?190:($key==='name'?100:150) ?>"></label><?php endforeach; ?><label>Message<textarea name="message" class="form-control" rows="5" minlength="10" maxlength="5000" required><?= e(post('message')) ?></textarea></label><button class="btn btn-accent w-100">Send message ↗</button></form></div></section><?php require ROOT.'/includes/footer.php'; ?>
